it('V8 完整保留扩展策略并拒绝内外声明不一致',()=>{
 const base=JSON.parse(extendedCapture().packageJson)
 const settings={definitions:base.extensions,fieldAccess:base.extensions.fields.map((_:unknown,index:number)=>({showInUserApp:index===0,userAppEditable:index===0})),preferReported:true,locationShowInUserApp:true}
 const value={contract:'thingslink.device-type-product.v8',functions:base.functions,scopes:base.scopes,base,extensions:settings}
 const details=readProductDefinitionPackageDetails(JSON.stringify(value),'CURRENT_TYPE_CAPTURE')
 expect(details.extensionSettings?.fieldAccess[0]).toEqual({showInUserApp:true,userAppEditable:true})
 expect(details.extensionSettings?.preferReported).toBe(true)
 const invalid=structuredClone(value);invalid.extensions.fieldAccess[0].showInUserApp=false
 expect(()=>readProductDefinitionPackageDetails(JSON.stringify(invalid),'CURRENT_TYPE_CAPTURE')).toThrow()
 const altered=structuredClone(value);altered.functions={...altered.functions,type:{...altered.functions.type,name:'different'}}
 expect(()=>readProductDefinitionPackageDetails(JSON.stringify(altered),'CURRENT_TYPE_CAPTURE')).toThrow()
 for(const capture of [dataCapture(true),applicationCapture(true,true),taskCapture(true,true,true),ruleCapture(true,true,true,true)]){
  const nested=JSON.parse(capture.packageJson),extra={definitions:nested.extensions,fieldAccess:nested.extensions.fields.map(()=>({showInUserApp:false,userAppEditable:false})),preferReported:false,locationShowInUserApp:false}
  const composite={contract:'thingslink.device-type-product.v8',functions:nested.functions,scopes:nested.scopes,base:nested,extensions:extra}
  const decoded=readProductDefinitionPackageDetails(JSON.stringify(composite),'CURRENT_TYPE_CAPTURE')
  expect(decoded.extensionSettings?.fieldAccess).toHaveLength(nested.extensions.fields.length)
  expect(!!decoded.rules).toBe(nested.scopes.rules);expect(!!decoded.tasks).toBe(nested.scopes.tasks);expect(!!decoded.data).toBe(nested.scopes.data);expect(!!decoded.thingsX).toBe(nested.scopes.thingsX)
 }
})
it('V9 只接受同包规则中的当前设备函数并拒绝外部动作',()=>{
 const base=JSON.parse(ruleCapture(false,true,false,false).packageJson),fn={format:'COMMON_JS',source:'function(){return {};}'}
 const actionRules=(rules:unknown[])=>({rules})
 const report={name:'设备处理',description:null,tags:{},source:'SELF_TYPE',sourceState:'PAUSED',activationRequired:true,trigger:{kind:'ATTRS_RPT',identifier:null,filter:null},actions:[{nodeType:'current-device-properties-function',config:{function:fn}}]}
 const event={...report,name:'事件处理',trigger:{kind:'EVENT_RPT',identifier:'alarm',filter:null},actions:[{nodeType:'event-cloud-function',config:{function:fn}}]}
 const push={...report,name:'下发数据',trigger:{kind:'ATTRS_PUSH',identifier:null,filter:null},actions:[{nodeType:'current-device-data-function',config:{function:fn,protocol:'MQTT',streamIdentifier:'AppJSON'}}]}
 const pushTcp={...push,name:'下发TCP',actions:[{nodeType:'current-device-data-function',config:{function:fn,protocol:'TCP',streamIdentifier:'PayloadHEX'}}]}
 const value={contract:'thingslink.device-type-product.v9',functions:base.functions,scopes:base.scopes,base,actionRules:actionRules([report,event,push,pushTcp])}
 const parsed=readProductDefinitionPackageDetails(JSON.stringify(value),'CURRENT_TYPE_CAPTURE')
 expect(parsed.actionRules?.rules.map(rule=>rule.name)).toEqual(['设备处理','事件处理','下发数据','下发TCP'])
 expect(parsed.actionRules?.rules[3]?.actions[0]?.nodeType).toBe('current-device-data-function')
 for(const mutate of [(p:any)=>p.actionRules.rules[0].actions[0].nodeType='target-device-properties-function',(p:any)=>p.actionRules.rules[1].trigger.identifier=null,(p:any)=>p.actionRules.rules[1].actions[0].nodeType='current-device-properties-function',(p:any)=>p.actionRules.rules[2].trigger.identifier='stream',(p:any)=>p.actionRules.rules[2].trigger.filter={operator:'ALL',conditions:[],groups:[]},(p:any)=>p.actionRules.rules[2].actions[0].config.streamIdentifier='Absent',(p:any)=>p.actionRules.rules[2].actions[0].config.protocol='TCP',(p:any)=>p.actionRules.rules[2].actions[0].config.delaySeconds=1,(p:any)=>p.actionRules.rules[2].actions[0].nodeType='event-cloud-function']){const invalid=structuredClone(value);mutate(invalid);expect(()=>readProductDefinitionPackageDetails(JSON.stringify(invalid),'CURRENT_TYPE_CAPTURE')).toThrow()}
 const noData=JSON.parse(ruleCapture(false,false,false,false).packageJson)
 expect(()=>readProductDefinitionPackageDetails(JSON.stringify({contract:'thingslink.device-type-product.v9',functions:noData.functions,scopes:noData.scopes,base:noData,actionRules:actionRules([push])}),'CURRENT_TYPE_CAPTURE')).toThrow()
})
it('V10 固定每日计划保留时区和时间并拒绝隐藏无效字段',()=>{
 const base=JSON.parse(taskCapture().packageJson),commandKey=base.tasks.tasks[0].commandKey
 const dailyTasks={tasks:[{name:'每日任务',description:null,target:'SELF_TYPE',commandKey,input:{},sourceState:'PAUSED',activationRequired:true,commandRequestId:null,plan:{zoneMode:'FOLLOW_PROJECT',zone:null,times:['08:00','17:30'],weekdays:[1,5]}}]}
 const value={contract:'thingslink.device-type-product.v10',functions:base.functions,scopes:base.scopes,base,dailyTasks}
 expect(readProductDefinitionPackageDetails(JSON.stringify(value),'CURRENT_TYPE_CAPTURE').dailyTasks?.tasks[0]?.plan.times).toEqual(['08:00','17:30'])
 const invalid=structuredClone(value);invalid.dailyTasks.tasks[0].plan.weekdays=[5,1]
 expect(()=>readProductDefinitionPackageDetails(JSON.stringify(invalid),'CURRENT_TYPE_CAPTURE')).toThrow()
 const rulesBase=JSON.parse(ruleCapture(true,true,true,true).packageJson),settings={definitions:rulesBase.extensions,fieldAccess:rulesBase.extensions.fields.map(()=>({showInUserApp:false,userAppEditable:false})),preferReported:false,locationShowInUserApp:false}
 const withSettings={contract:'thingslink.device-type-product.v8',functions:rulesBase.functions,scopes:rulesBase.scopes,base:rulesBase,extensions:settings}
 const actionRules={rules:[{name:'上报后处理',description:null,tags:{},source:'SELF_TYPE',sourceState:'PAUSED',activationRequired:true,trigger:{kind:'ATTRS_RPT',identifier:null,filter:null},actions:[{nodeType:'current-device-command-function',config:{function:{format:'COMMON_JS',source:'function(){return {};}'}}}]}]}
 const withActions={contract:'thingslink.device-type-product.v9',functions:rulesBase.functions,scopes:rulesBase.scopes,base:withSettings,actionRules}
 const combined={contract:'thingslink.device-type-product.v10',functions:rulesBase.functions,scopes:rulesBase.scopes,base:withActions,dailyTasks:{tasks:[{...dailyTasks.tasks[0],commandKey:rulesBase.tasks.tasks[0].commandKey}]}}
 const parsed=readProductDefinitionPackageDetails(JSON.stringify(combined),'CURRENT_TYPE_CAPTURE');expect(parsed.dailyTasks?.tasks).toHaveLength(1);expect(parsed.actionRules?.rules).toHaveLength(1);expect(parsed.extensionSettings).toBeDefined()
})
