import Publisher from '../../src/features/device-types/DeviceTypeCurrentProductPublisher.vue'
import Settings from '../../src/features/device-types/DeviceTypeSettings.vue'
import ProductImporter from '../../src/features/device-types/DeviceTypeProductImport.vue'
import {productTransport,type ProductImportIntent} from '../../src/features/device-types/public-product-api'
import {decodeTypeProfile} from '../../src/features/device-types/profile-api'
import {createMemoryHistory,createRouter,RouterView} from 'vue-router'
import {session} from '../../src/core/session'
import {ApiError,IdentityChanged,changeIdentity} from '../../src/core/http'
import {currentProductPublicationTransport,decodeCurrentProductCapture,decodeCurrentProductPublication,prepareCurrentProductCapture,prepareCurrentProductPublish,type CurrentProductCapture,type CurrentProductPublication,type CurrentProductPublicationTransport} from '../../src/features/device-types/current-product-publication-api'
const id=(n:number)=>`00000000-0000-4000-8000-${String(n).padStart(12,'0')}`,project=id(1),type=id(2),captureId=id(3),productId=id(4),version=id(5)
const scopes={functions:true,extensions:false,rules:false,tasks:false,data:false,thingsX:false},optional=['extensions','rules','tasks','data','thingsX'],exact='0.12345678901234567890123456789'
const packageJson=`{"contract":"thingslink.device-type-product.v2","functions":{"contract":"thingslink.device-type-template.v1","type":{"name":"当前来源类型","description":"完整功能说明","tags":{},"deviceKind":"DIRECT","payloadProtocol":"STANDARD","networkType":"WIFI"},"properties":[{"propertyKey":"temperature","name":"精确温度","sortOrder":2,"minimumValue":${exact},"dataType":"NUMBER"}],"events":[{"eventKey":"notice","name":"通知事件","sortOrder":0,"parameters":[]}],"commands":[{"commandKey":"restart","name":"重启命令","sortOrder":0,"inputSchema":"{}","outputSchema":"{}"}],"modelSnapshot":{"properties":{},"events":{},"commands":{}}},"scopes":${JSON.stringify(scopes)},"sections":${JSON.stringify(Object.fromEntries(optional.map(k=>[k,{selected:false,status:'NOT_CAPTURED'}])))}}`
const capture=()=>({captureId,sourceDeviceTypeId:type,packageJson,packageDigest:'a'.repeat(64),modelDigest:'b'.repeat(64),scopes:{...scopes},capturedAt:new Date(Date.now()-60000).toISOString(),expiresAt:new Date(Date.now()+86400000).toISOString()}) as CurrentProductCapture
const publication=(saved:CurrentProductCapture,patch:Record<string,unknown>={})=>({sourceKind:'CURRENT_TYPE_CAPTURE',sourceCaptureId:saved.captureId,product:{productId,versionId:version,currentVersionId:version,sequence:1,name:'当前来源类型',publisherLabel:'合成署名',sourceMode:'CURRENT_TYPE_CAPTURE',packageJson:saved.packageJson,packageDigest:saved.packageDigest,modelDigest:saved.modelDigest,publishedAt:'2026-10-29T00:00:00Z',revision:'1',state:'PUBLISHED',withdrawnAt:null,...patch}}) as CurrentProductPublication
function owned(saved:CurrentProductCapture,patch:Record<string,unknown>={}){
 const {product:{productId,versionId,sequence,name,publisherLabel,packageDigest,publishedAt,revision,state,withdrawnAt}}=publication(saved,patch)
 return {sourceKind:'CURRENT_TYPE_CAPTURE' as const,sourceCaptureId:saved.captureId,sourceDeviceTypeId:type,product:{productId,versionId,sequence,name,publisherLabel,packageDigest,publishedAt,revision,state,withdrawnAt}}
}
const settingsProfile=()=>decodeTypeProfile({type:{id:type,projectId:project,name:'当前类型',typeKey:'type_1',deviceKind:'DIRECT',networkType:'WIFI',payloadProtocol:'STANDARD',status:'PUBLISHED',version:1,productKey:null,createdAt:'2026-10-28T01:00:00Z'},description:'说明',tags:{},revision:'0',profileToken:'a'.repeat(64)},project,type)
let wrapper:VueWrapper|undefined
function port(){const saved=capture();return{saved,api:{owned:vi.fn().mockResolvedValue({items:[],total:'0',available:true}),capture:vi.fn().mockResolvedValue(saved),captured:vi.fn().mockResolvedValue(saved),publish:vi.fn().mockResolvedValue(publication(saved)),published:vi.fn().mockResolvedValue(publication(saved))}}}
async function render(api:CurrentProductPublicationTransport){wrapper=mount(Publisher,{props:{typeId:type,transport:api},attachTo:document.body,global:{plugins:[ElementPlus]}});await flushPromises();return wrapper}
async function renderSettings(){
 const router=createRouter({history:createMemoryHistory(),routes:[{path:'/type',component:Settings,props:{profile:settingsProfile()}}]})
 await router.push('/type');await router.isReady()
 wrapper=mount(RouterView,{attachTo:document.body,global:{plugins:[ElementPlus,router]}});await flushPromises()
 return wrapper
}
function button(name:string){const b=[...document.querySelectorAll<HTMLButtonElement>('button')].find(n=>n.textContent?.trim()===name);expect(b,name).toBeDefined();return new DOMWrapper(b!)}
async function click(name:string){await button(name).trigger('click');await flushPromises()}
async function confirm(){await wrapper!.get('input[aria-label="当前类型分享署名"]').setValue('合成署名');wrapper!.findComponent(ElCheckbox).vm.$emit('update:modelValue',true);await flushPromises()}
const scopeSwitches=()=>wrapper!.findAllComponents(ElSwitch).slice(1)
const scopeSwitch=(label:string)=>scopeSwitches().find(box=>box.find(`input[aria-label="${label}"]`).exists())!
beforeEach(()=>{vi.stubGlobal('crypto',webcrypto);changeIdentity();session.ready=true;session.transitioning=false;session.user={accountId:id(9),currentProjectId:project,projectRole:'OWNER',permissions:['device:read','device:update']} as never;session.projects=[{id:project,myRole:'OWNER',status:'ACTIVE'}]})
afterEach(()=>{wrapper?.unmount();wrapper=undefined;session.user=null;session.projects=[];document.body.innerHTML='';vi.restoreAllMocks();vi.unstubAllGlobals()})
it('当前功能固定预览后署名确认才发布，独立原键回读且不创建模板',async()=>{
 const {api}=port();await render(api);expect(api.capture).not.toHaveBeenCalled();await click('生成固定预览');expect(api.capture).toHaveBeenCalledTimes(1);expect(api.captured.mock.calls[0]![0]).toBe(api.capture.mock.calls[0]![0]);expect(api.capture.mock.calls[0]![0].body).toEqual({scopes});expect(wrapper!.text()).toContain('温度');expect(wrapper!.text()).toContain('通知事件');expect(wrapper!.text()).toContain('重启命令');expect(wrapper!.text()).toContain(exact);expect(api.publish).not.toHaveBeenCalled();expect(button('确认发布功能定义').attributes('disabled')).toBeDefined();await confirm();await click('确认发布功能定义');expect(api.publish).toHaveBeenCalledTimes(1);const intent=api.publish.mock.calls[0]![0];expect(intent.body).toEqual({captureId,expectedPackageDigest:'a'.repeat(64),productId:null,revision:null,publisherLabel:'合成署名'});expect(api.published.mock.calls[0]![0]).toBe(intent);expect(wrapper!.text()).toContain(productId);expect(wrapper!.text()).toContain('功能定义已发布');expect(wrapper!.emitted('published')).toHaveLength(1);expect(wrapper!.emitted('locked')?.at(-1)).toEqual([false])
})
it('取消已生成预览不公开产品，不把取消冒零技术记录',async()=>{
 const {api}=port();await render(api);await click('生成固定预览');expect(wrapper!.text()).toContain('取消只取消公开发布，不删除已生成的预览');await click('取消发布');expect(api.capture).toHaveBeenCalledTimes(1);expect(api.publish).not.toHaveBeenCalled();expect(wrapper!.emitted('close')).toHaveLength(1);expect(wrapper!.emitted('published')).toBeUndefined()
})
it('发布确认后关闭弹窗并回读产品 ID 和发布时间，重进设置仍显示更新和撤回',async()=>{
 const {api,saved}=port()
 for(const name of ['owned','capture','captured','publish','published'] as const)vi.spyOn(currentProductPublicationTransport,name).mockImplementation(api[name])
 await renderSettings()
 const descriptionSection=wrapper!.get('.type-settings > section:first-child')
 expect(descriptionSection.text()).toBe('类型描述编辑')
 expect(descriptionSection.get('button').text()).toBe('编辑')
 expect(wrapper!.find('.product-publication-facts').exists()).toBe(false)
 await click('发布');await click('生成固定预览');await confirm()
 api.owned.mockResolvedValue({items:[owned(saved)],total:'1',available:true})
 await click('确认发布功能定义')
 expect(api.published).toHaveBeenCalledWith(api.publish.mock.calls[0]![0],expect.any(AbortSignal))
 expect(wrapper!.get('.product-publication-facts').text()).toContain(productId)
 expect(wrapper!.get('time').text()).toBe('2026-10-29 08:00:00')
 expect(wrapper!.findComponent(Publisher).exists()).toBe(false)
 expect(button('更新').exists()).toBe(true)
 expect(button('撤回').exists()).toBe(true)
 wrapper!.unmount();await renderSettings()
 expect(wrapper!.get('.product-publication-facts').text()).toContain(productId)
 await click('更新')
 expect(wrapper!.text()).toContain('更新已发布的产品，产品 ID 保持不变。')
 expect(api.publish).toHaveBeenCalledTimes(1)
})
