// 复用既有提示PNG测试的本地有效PNG构造；160px且大于16KiB，防止把完整提示图误缩成功能小图标。
function applicationPng(){const width=160,height=128,raw=Buffer.alloc((width*4+1)*height);let seed=16823;for(let y=0;y<height;y++){const row=y*(width*4+1);for(let x=0;x<width*4;x++){seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;raw[row+1+x]=x%4===3?255:seed&255}}function chunk(name:string,data:Buffer){const out=Buffer.alloc(data.length+12);out.writeUInt32BE(data.length);out.write(name,4);data.copy(out,8);let crc=0xffffffff;for(const byte of out.subarray(4,out.length-4)){crc^=byte;for(let bit=0;bit<8;bit++)crc=crc&1?0xedb88320^(crc>>>1):crc>>>1}out.writeUInt32BE((crc^0xffffffff)>>>0,out.length-4);return out}const ihdr=Buffer.alloc(13);ihdr.writeUInt32BE(width);ihdr.writeUInt32BE(height,4);ihdr[8]=8;ihdr[9]=6;const bytes=Buffer.concat([Buffer.from('89504e470d0a1a0a','hex'),chunk('IHDR',ihdr),chunk('IDAT',deflateSync(raw)),chunk('IEND',Buffer.alloc(0))]);return{mediaType:'image/png',width,height,sha256:createHash('sha256').update(bytes).digest('hex'),base64:bytes.toString('base64')}}
const portableImage=applicationPng()
