 return{...capture(),scopes:selected,packageJson:JSON.stringify({contract:'thingslink.device-type-product.v5',functions:previous.functions,scopes:selected,extensions:extensions?previous.extensions:null,data:withData?previous.data:null,thingsX:{userAdd:{allowUserAdd:false,codeMode:'BUSINESS_KEY',visibleInAddDirectory:false,promptText:'保留用户添加说明',showPromptImage:false,promptImage:portableImage},thingsXs:{customEnabled:false,propertyKeys:['humidity','temperature']},thingsAdmin:{customEnabled:true,propertyKeys:['temperature','humidity']}},sections:Object.fromEntries(['rules','tasks',...(!extensions?['extensions']:[]),...(!withData?['data']:[])].map(k=>[k,{selected:false,status:'NOT_CAPTURED'}]))})}
