const exactTaskInput='9007199254740993.1234567890123456789'
function taskCapture(extensions=false,withData=false,application=false):CurrentProductCapture{
 const previous=JSON.parse(applicationCapture(extensions,withData).packageJson),selected={...scopes,extensions,data:withData,thingsX:application,tasks:true};previous.functions.commands[0].inputSchema=JSON.stringify({type:'object',properties:{amount:{type:'number'},nested:{type:'object'}},required:['amount']});previous.functions.modelSnapshot.commands.restart={inputSchema:JSON.parse(previous.functions.commands[0].inputSchema),outputSchema:{}}
 const tasks=[{name:'手动重启',description:'完整手动命令输入',target:'SELF_TYPE',schedule:'MANUAL',commandKey:'restart',input:{amount:'__exact_task_decimal__',nested:{text:'原常量',reference:id(77)}},sourceState:'ACTIVE',activationRequired:true},{name:'备用重启',description:null,target:'SELF_TYPE',schedule:'MANUAL',commandKey:'restart',input:{amount:2},sourceState:'PAUSED',activationRequired:true}]
 return{...capture(),scopes:selected,packageJson:JSON.stringify({contract:'thingslink.device-type-product.v6',functions:previous.functions,scopes:selected,extensions:extensions?previous.extensions:null,data:withData?previous.data:null,thingsX:application?previous.thingsX:null,tasks:{tasks},sections:Object.fromEntries(['rules',...(!extensions?['extensions']:[]),...(!withData?['data']:[]),...(!application?['thingsX']:[])].map(k=>[k,{selected:false,status:'NOT_CAPTURED'}]))}).replace('"__exact_task_decimal__"',exactTaskInput)}
}
