const exactRuleCondition='0.12345678901234567890123456789',ruleSource='module.exports = attributes => {\r\n  // 业务常量保持原文\r\n  return attributes;\r\n};\r\n',secondRuleSource='attributes => ({...attributes})\r\n'
function ruleCapture(extensions=false,withData=false,application=false,withTasks=false):CurrentProductCapture{
 const previous=JSON.parse(taskCapture(extensions,withData,application).packageJson.replace(exactTaskInput,'"__preserve_task_input__"')),selected={...scopes,extensions,data:withData,thingsX:application,tasks:withTasks,rules:true}
 const rules=[{name:'公开上报规则',description:'保留\r\n说明',tags:{'位置':' 原文 ','业务常量':id(77)},source:'SELF_TYPE',sourceState:'ACTIVE',activationRequired:true,trigger:{kind:'ATTRS_RPT_PREPROC',identifier:null,filter:{operator:'ALL',conditions:[{pointer:'/temperature',operator:'GTE',value:'__exact_rule_condition__'},{pointer:'/humidity',operator:'EXISTS'}],groups:[{operator:'ANY',conditions:[{pointer:'/humidity',operator:'EQ',value:5}],groups:[]}]}},functions:[{format:'COMMON_JS',source:ruleSource},{format:'FUNCTION_EXPRESSION',source:secondRuleSource}]},{name:'公开下发规则',description:null,tags:{},source:'SELF_TYPE',sourceState:'PAUSED',activationRequired:true,trigger:{kind:'ATTRS_PUSH_PREPROC',identifier:null,filter:null},functions:[{format:'FUNCTION_EXPRESSION',source:'attributes => attributes\r\n'}]}]
 return{...capture(),scopes:selected,packageJson:JSON.stringify({contract:'thingslink.device-type-product.v7',functions:previous.functions,scopes:selected,extensions:extensions?previous.extensions:null,data:withData?previous.data:null,thingsX:application?previous.thingsX:null,tasks:withTasks?previous.tasks:null,rules:{rules},sections:Object.fromEntries([...(!extensions?['extensions']:[]),...(!withData?['data']:[]),...(!application?['thingsX']:[]),...(!withTasks?['tasks']:[])].map(k=>[k,{selected:false,status:'NOT_CAPTURED'}]))}).replace('"__exact_rule_condition__"',exactRuleCondition).replace('"__preserve_task_input__"',exactTaskInput)}
}
