it('产品导入同名409保业务原因并提示重读，10014原键UNKNOWN与降权只读恢复保持',async()=>{
 const api=await renderProductImporter(ruleCapture());api.create.mockRejectedValueOnce(new ApiError('规则名称已存在：公开上报规则',409));await wrapper!.get('input[aria-label="产品导入新类型名称"]').setValue('新类型');await click('确认按此发布版本创建');expect(wrapper!.text()).toContain('规则名称已存在：公开上报规则');expect(wrapper!.text()).toContain('重新按产品 ID 读取当前版本后核对');expect(wrapper!.emitted('created')).toBeUndefined();expect(api.imported).not.toHaveBeenCalled();const rejected=api.create.mock.calls[0]![0]
 await click('读取当前发布版本');await vi.waitFor(()=>expect(wrapper!.find('.product-import-scope').exists()).toBe(true));api.create.mockRejectedValueOnce(new ApiError('原件暂不可回放',409,10014));api.imported.mockRejectedValueOnce(new ApiError('尚未读到',404));await click('确认按此发布版本创建');const original=api.create.mock.calls[1]![0],snapshot=JSON.stringify(original);expect(original.key).not.toBe(rejected.key);expect(wrapper!.text()).toContain('原创建结果未知');session.user={...session.user!,projectRole:'VIEWER',permissions:['device:read']};session.projects=[{id:project,myRole:'VIEWER',status:'ARCHIVED'}];await wrapper!.setProps({disabled:true});await click('读取原产品导入回执');expect(wrapper!.text()).toContain('仍保持未知');expect(wrapper!.emitted('created')).toBeUndefined();await click('读取原产品导入回执');expect(api.create).toHaveBeenCalledTimes(2);expect(api.imported.mock.calls.every(([intent])=>intent===original)).toBe(true);expect(JSON.stringify(original)).toBe(snapshot);expect(wrapper!.emitted('created')).toEqual([[id(90)]])
})
